  'wall.hektor.msg': 'Hekthor, ти мій найбільший герой, мій найкращий друг, мій вірний товариш, мій безжальний наставник — ти найпрекрасніша історія мого життя. Завдяки тобі я заснував собачу релігію і зрозумів, що в моїй любові немає нічого особливого — кожен, хто бодай раз любив собаку, відчуває в серці точнісінько те саме. Дякую за наше найкраще спільне життя. Я люблю тебе.',
