  "heroglyph.flow.dogCharacter.slideLabel": "СЛАЙД",
  "heroglyph.flow.dogCharacter.slideAriaLabel": "Наступний слайд персонажа",
  "heroglyph.flow.dogCharacter.slide.guardian.title": "Охоронець (Око Дого)",
  "heroglyph.flow.dogCharacter.slide.player.title": "Гравець (Крилатий м'яч)",
  "heroglyph.flow.dogCharacter.slide.energizer.title": "Енерджайзер (Повний заряд)",
  "heroglyph.flow.dogCharacter.slide.maverick.title": "Бунтар (Піратський знак)",
  "heroglyph.flow.dogCharacter.slide.waterlover.title": "Водолюб (Хвилі)",
  "heroglyph.flow.dogCharacter.slide.gourmet.title": "Гурман (Безкінечна миска)",
  "heroglyph.flow.dogCharacter.slide.lover.title": "Пестунчик (Амур)",
  "heroglyph.flow.dogCharacter.slide.chiller.title": "Лежень (Диван)",
  "heroglyph.flow.dogCharacter.slide.guardian.desc": "Стереже двері, ніби це брама в потойбіччя. Спершу гавкає, а питання — ніколи.",
  "heroglyph.flow.dogCharacter.slide.player.desc": "Продасть душу за ще один кидок м'яча. Найбільша радість — улюблена іграшка.",
  "heroglyph.flow.dogCharacter.slide.energizer.desc": "Без вимикача. Без батарейок. Найчастіше питання: на чому сидить цей пес?",
  "heroglyph.flow.dogCharacter.slide.maverick.desc": "Сучасний пірат зі своїм світом і своїми правилами. Вибірковий слух — його перший закон.",
  "heroglyph.flow.dogCharacter.slide.waterlover.desc": "Пси бувають двох типів — і один із них легко сплутати з рибою. Мокра шерсть: 100 % щастя.",
  "heroglyph.flow.dogCharacter.slide.gourmet.desc": "Їжа — це місія. Повна віддача, нуль вагань — і доїсть усе, що лишилося у твоїй тарілці.",
  "heroglyph.flow.dogCharacter.slide.lover.desc": "Чужих для нього не існує. Листоношу зустрічає як давно втрачену споріднену душу. Щоразу.",
  "heroglyph.flow.dogCharacter.slide.chiller.desc": "Опанував давнє мистецтво нічого не робити — і робить це красиво.",
  "heroglyph.flow.message.done": "Готово",
