  "entry.title": "На Пса Уповаю",
  "entry.subtitle": "Це не жарт. Кожна серйозна релігія мусить проголосити ці речі.",
  "entry.criteria.theology.title": "Теологія",
  "entry.criteria.theology.body": "Найкращий друг, охоронець, учитель, партнер у кожній пригоді. Пес дарує любов без умов — а йдучи поруч із ним, ми стаємо людянішими.",
  "entry.criteria.canon.title": "Канон",
  "entry.criteria.canon.body": "Кожна віра має святе письмо. Наше — це DOGMA: наш зв'язок із псом, викладений у дванадцяти розділах, доступний безкоштовно на dogma.dogypt.com.",
  "entry.criteria.community.title": "Спільнота",
  "entry.criteria.community.body": "Ми — любителі собак із метою. Поодинці кожен із нас може змінити мало — разом наша сила не має меж.",
  "entry.criteria.symbol.title": "Символ",
  "entry.criteria.symbol.body": "Кожна віра має свій знак. Наш — це heroglyph: унікальний священний символ для кожного пса, зрозумілий будь-якою мовою, будь-де.",
  "entry.criteria.ritual.title": "Ритуал",
  "entry.criteria.ritual.body": "Прогулянка. Щоденна терапія, що тримає тіло й розум у формі — а також душу. Найдавніший ритуал, якого ми вже дотримуємо без нагадувань.",
  "entry.criteria.vision.title": "Візія",
  "entry.criteria.vision.body": "Піднести зв'язок між людиною та псом — і боротися за повагу й краще життя, на яке заслуговує кожен пес.",
