  // ── /pack a zvyšok appky — preklad 4. 10. 2026 (plany/preklad-pack-2026-10-04) ──
  "privacy.s12.title": "12. У зграї: що бачать інші Члени",
  "privacy.s12.body": "Стаття 3 описує публічний GodsGrid. У зграї — у зоні лише для Членів — інші авторизовані Члени бачать більше: ваше ім'я, ваш догіптянський порядковий номер, ім'я та фото вашого пса, атрибути, які ви заповнили про пса, походи, які ви записали або оголосили, ваші оцінки й коментарі та все, що ви написали у своєму профілі. Вони не бачать вашу електронну адресу, поштову адресу, платіжні дані чи ваші повідомлення з будь-ким іншим. Коли ви оголошуєте похід відкритим, маршрут, дата та ваш пес стають видимими для кожного Члена, щоб він міг попросити приєднатися — саме це означає оголошення. Похід, який ви лишаєте приватним, бачите лише ви і ті, хто вже йде. Який із цих двох варіантів обрати, вирішуєте ви, і можете змінити це будь-коли.",
  "privacy.s13.title": "13. Повідомлення та скарги",
  "privacy.s13.body": "Приватні повідомлення між Членами зберігаються в нашій базі даних (Supabase), щоб розмови зберігалися між сесіями. Правова підстава: ст. 6(1)(b) GDPR — вони є частиною членства, за яке ви заплатили. Ми не читаємо їх регулярно і ніколи не використовуємо для реклами чи профілювання. Ми відкриваємо розмову лише тоді, коли на неї надійшла скарга, коли ми розслідуємо конкретне порушення чи інцидент безпеки, або коли цього вимагає закон. Скарга зберігає вибрану вами причину, вашу необов'язкову примітку та посилання на те, що ви повідомили, — а не окрему копію цього. Блокування зберігається як пара ідентифікаторів членів. Якщо ви видалите свій акаунт, ваші повідомлення зникнуть разом з ним; копія в гілці іншої людини залишається, показана як від видаленого члена, бо ця розмова належить і їй.",
  "terms.s12.title": "12. Контент, який ви публікуєте",
  "terms.s12.body": "Поруч зі своїм HEROGLYPH ви можете публікувати в зграї контент: фото з походів, маршрути та місця, описи походів, оцінки, коментарі й запитання та все, що ви напишете у своєму профілі. Коли ви позначите похід як пройдений, інші Члени побачать ваше ім'я та псів, які пройшли його з вами. Ви зберігаєте право власності на все, що публікуєте. Публікуючи це, ви надаєте DOGYPT s.r.o. всесвітню, безоплатну, невиключну ліцензію зберігати, показувати й адаптувати цей контент з метою роботи та просування Послуги — наприклад, показати ваше фото з походу на карті, у списку походів або на картці для поширення. Ліцензія діє, доки контент є в Послузі; видалення контенту чи акаунта припиняє її, окрім резервних копій, які спливають за звичним циклом. Ми не продаємо ваш контент і не ліцензуємо його нікому іншому для власного використання. Публікуйте лише те, на що маєте право, — включно з фото, зробленими кимось іншим, і людьми, які на них впізнавані.",
  "terms.s13.title": "13. Повідомлення між Членами",
  "terms.s13.body": "Члени можуть писати одне одному напряму. Повідомлення приватні між учасниками — ми не читаємо їх регулярно і ніколи не використовуємо для реклами. Вони зберігаються на наших серверах, щоб розмова була там і після вашого повернення, і ми можемо прочитати розмову у трьох випадках: коли хтось на неї скаржиться, коли ми розслідуємо конкретне порушення чи інцидент безпеки, або коли цього вимагає закон. Іншого Члена можна заблокувати будь-коли; блокування діє миттєво й в обидва боки. Ставтеся до повідомлень як до будь-якої іншої онлайн-розмови — не надсилайте платіжні дані, паролі чи документи, які не хочете, щоб зберігалися.",
  "terms.s14.title": "14. Скарги та модерація",
  "terms.s14.body": "Профілі, походи й розмови можна поскаржитися. Скарга надходить до нас, і її читає людина — сьогодні це засновник, Матей Стахо. Наша мета — розглянути кожну скаргу протягом 7 днів. Залежно від того, що ми виявимо, ми можемо не робити нічого, видалити контент, попередити Члена, обмежити те, що він може публікувати, або закрити його акаунт. Якщо ми вживемо заходів щодо вашого контенту, ми повідомимо причину електронною поштою, і ви можете відповісти й оскаржити це. Ми також можемо видалити контент за власною ініціативою, якщо він порушує Статтю 7. Умисне або повторюване порушення — переслідування, спам, фальшиві походи, контент із неповнолітніми — закриває акаунт без подальшого попередження.",
  "dogPage.bonesForDog": "Приєднайся через цю сторінку, і {dog} отримає 20 BONES.",
  "dogPage.bonesNote": "BONES — валюта DOGYPT, вони потрапляють на рахунок власника.",
