  "pack.cal.life.tgtBody": "до п'яти додаткових років, які може додати холістичний догляд — стрункість, рух у природному терені, зуби, сон і якомога менше зайвої хімії.",
  "pack.cal.life.tgtSrc": "Приблизна оцінка, не обіцянка. Виміряно з цього лише одне: сама стрункість додала лабрадорам 1,8 року (Purina Life Span Study, JAVMA 2002).",
  "pack.cal.life.intro": "Нижче ти бачиш усе життя свого пса в блоках. Один блок = один тиждень, один рядок = один рік. З одного боку це тривожно, з іншого — саме те нагадування, що варто цінувати кожну мить і не відкладати речі на потім.",
  "pack.cal.life.fromBirth": "Рахується від народження",
  "pack.cal.life.daysLived": "днів найкращого життя",
  "pack.cal.life.days": "днів найкращого життя",
  "pack.cal.life.fromSince": "Рахується від",
  "pack.cal.life.together": "днів разом",
  "pack.cal.life.bestLife": "Прожив найкраще життя.",
  "pack.cal.life.zone": "Мало псів в історії дійшли сюди",
  "pack.cal.life.recTitle": "Довговічність псів — не випадковість",
  "pack.cal.life.recSub": "Нижче кілька рекордсменів, які дожили майже до 30 років. Довге й щасливе життя тримається здебільшого на твоїх щоденних рішеннях.",
  "pack.cal.life.recPrev": "Попередній",
  "pack.cal.life.recNext": "Наступний",
  "pack.cal.life.unverified": "неперевірено — тримається на слові власника",
  "pack.cal.life.tipsTitle": "Що ти можеш з цим зробити",
  "pack.cal.life.tipsSub": "Шість речей, важливіших за породу. Жодна не коштує грошей, усі коштують уваги.",
  "pack.cal.life.protoTitle": "Протокол довголіття",
  "pack.cal.life.protoBody": "Весь процес, на якому тримаються ці кілька порад, — харчування, навантаження, відпочинок і що варто виміряти. Він житиме в базі даних, яку оберігає ",
  "pack.cal.life.protoSoon": "Незабаром",
