  "pack.cal.life.rec.pebbles.exact": "22 роки 189 днів",
  "pack.cal.life.recSince": "з {year}",
  "pack.cal.life.tip.weight.title": "Стрункість — єдине, що доведено",
  "pack.cal.life.tip.weight.body": "З усього, що можна зробити для пса, одна річ має найтвердіший доказ впливу на тривалість життя: не дати йому набрати вагу. Різниця між струнким і трохи повним псом — це роки, не місяці. Ребра мають відчуватися без натискання.",
  "pack.cal.life.tip.move.title": "Рух у справжньому терені, а не коло навколо будинку",
  "pack.cal.life.tip.move.body": "Нерівна поверхня тримає в тонусі суглоби, мʼязи й голову. Кожен похід, який ти записуєш, перетворюється на цій сітці в темний тиждень — а темні тижні — єдине, на що ти справді можеш впливати.",
  "pack.cal.life.tip.food.title": "Їжа, яку пес впізнає як їжу",
  "pack.cal.life.tip.food.body": "Чим менше кроків між сировиною і мискою, тим менше може піти не так по дорозі. Гранули — це не щось погане, але й не повноцінний раціон — це скорочення шляху.",
  "pack.cal.life.tip.chem.title": "Хімія лише тоді, коли вона справді потрібна",
  "pack.cal.life.tip.chem.body": "Цілорічні протипаразитарні засоби, наркоз для зручності й антибіотики «на всякий випадок» — це рішення, не рутина. Питай при кожному з них: що станеться, якщо я це не дам? Де відповідь «нічого», там не давай.",
  "pack.cal.life.tip.stress.title": "Спокій важить так само, як і рух",
  "pack.cal.life.tip.stress.body": "Пес, який завжди напружений, спалює тіло зсередини. Непорушний сон, передбачуваний день і тиша після навантаження — це не лінь, а години, в які тіло себе відновлює.",
  "pack.cal.life.tip.protocol.title": "Протокол замість панічного бігу до ветеринара",
  "pack.cal.life.tip.protocol.body": "Дегельмінтизація, копрологія та аналізи крові мають у календарі свої вікна. Пес, якому двічі на рік перевіряють кров, не лікується — він на крок попереду.",
  "pack.cal.life.tip.joints.title": "Суглоби вирішують ДО того, як почнуть боліти",
  "pack.cal.life.tip.joints.body": "Твій пес зараз у сеніорському віці. Суглобовий курс має в календарі вікно від листопада — не тому, що він кульгає, а щоб ніколи не почав.",
