  "pack.nature.intro.eyebrow": "Три короткі квізи, один документ",
  "pack.nature.noDogs": "Цей квіз записує результат на картку пса, а на твоєму акаунті ще немає жодного пса.",
  "pack.nature.noDogsCta": "Назад до моїх псів",
