  "pack.nature.intro.title": "Хто твій пес?",
  "pack.nature.intro.body": "Двадцять два питання і один список. Ти дізнаєшся, з чого зроблений твій пес, яку роботу він виконує для родини і в який бік хилиться зараз його рівновага.",
  "pack.nature.intro.axis1": "Конституція",
