  "pack.nature.balance.body": "Конституція твого пса дана на все життя, але вона може вийти з рівноваги. Познач усе, що стосується, — скільки хочеш або й нічого.",
  "pack.nature.balance.none": "Нічого зі списку? Залиш порожнім і продовжуй — це найкраща відповідь, яка існує.",
  "pack.nature.progress": "Прогрес",
  "pack.nature.special.eyebrow": "Ще чотири — шукаємо особливі ролі",
  "pack.nature.special.body": "Ці чотири ролі стоять НАД головною. Більшість псів не має жодної — це нормально.",
  "pack.nature.special.cta": "Показати результат",
  "pack.nature.result.saved": "Збережено на картці твого пса",
  "pack.nature.result.savedAll": "Збережено на картках усіх псів",
  "pack.nature.ans.yes": "Так",
  "pack.nature.ans.sometimes": "Іноді",
  "pack.nature.ans.no": "Ні",
  "pack.network.ads.body": "Платна реклама — дуже неефективний спосіб знайти нових любителів собак, і спосіб викидати наші гроші великим корпораціям. Набагато краще працює винагороджувати учасників руху напряму за активність. Є один гачок: <strong style=\"font-weight:600\">це реально спрацює лише тоді, коли ти підеш і розкажеш про нас людям навколо себе</strong> :)",
  "pack.network.ads.header": "Чому саме так?",
  "pack.network.ads.wordAd": "реклама",
  "pack.network.ads.wordScroll": "незнайомець прогортає далі",
  "pack.network.allBones": "Усі {n}",
  "pack.network.back": "Назад",
  "pack.network.bonesLabel": "Твої BONES",
