  "pack.network.bonesUnit": "bones",
  "pack.network.capHintLog": "Ліміт 1:1 — подарунок може зрівняти лише те, що ти вже прожив.",
  "pack.network.capHintRow": "Ліміт 1:1 — подарунок зрівнює те, що ти прожив",
  "pack.network.capped.none": "Із цього переказу жодної відданості — твої подарунки вже зрівнюють усе, що ти прожив. BONES усе одно пройдуть. <i>Гроші подвоюють роки, ніколи їх не замінюють.</i>",
  "pack.network.capped.room": "Ліміт на <b style=\"color:#2a1608\">{room}</b> — подарунок може зрівняти лише те, що ти вже прожив ({lived} відданості наразі). BONES усе одно пройдуть; честь чекає на дні.",
  "pack.network.chainFirstInvite": "твоє перше запрошення",
