  "pack.network.eyebrow": "DOGYPT росте завдяки тобі",
  "pack.network.generatingLink": "Генеруємо твоє посилання…",
  "pack.network.linkFailed": "Не вдалося завантажити твоє запрошувальне посилання.",
  "pack.network.linkRetry": "Спробувати знову",
  "pack.network.groupDirect": "напряму",
  "pack.network.groupTheirBrings": "їхні запрошення",
  "pack.network.inLine": "У твоїй лінії",
  "pack.network.info.bones.body": "BONES — внутрішня валюта DOGYPT, жартівлива назва для справжньої речі. Пес платить кістками; ми теж. Ти <b>заробляєш</b> їх, приводячи любителів собак у зграю й рухаючи рух вперед, і <b>витрачаєш</b> їх всередині DOGYPT: підтримуючи збори для притулків, отримуючи мерч, а пізніше платячи іншим догіптянам за те, що вони створюють. <b>{n} BONES = 1 €.</b>",
  "pack.network.info.bones.cap": "Що таке BONES?",
  "pack.network.info.why.body": "Рух такого масштабу не купити — жодний бюджет не досягне незнайомця так, як один догіптянин досягає друга. Тож зграя кладе винагороду туди, де є досяжність, — до тебе. Коли хтось приєднується через твоє посилання, ти отримуєш <b>{l1} BONES</b>; коли він приводить когось, ти отримуєш ще <b>{l2}</b>. Кожен догіптянин, що поширює слово, не продавець — він місіонер, і ми шануємо цю роботу.",
  "pack.network.info.why.cap": "Чому ми просимо тебе",
  "pack.network.intro": "Рух росте лише тоді, коли його учасники несуть послання і приводять нових людей. Тож ми просимо тебе напряму: <strong style=\"color:#2a1608;font-weight:600\">запроси любителів собак, яких знаєш</strong>. Ось точно, як це працює.",
  "pack.network.inviteLinkHeader": "Твоє запрошувальне посилання",
