  "onepage.hbook.0.title": "Колись давно…",
  "onepage.hbook.0.glyph": "Heroglyph Hekthor",
  "onepage.hbook.0.sub": "Hekthor · пес #1",
  "onepage.hbook.0.cap": "Дзеркало",
  "onepage.hbook.1.ini": "Н",
  "onepage.hbook.1.lead": "ародився небажаним. Викинутий у коробці, де з братами чекав на смерть.",
  "onepage.hbook.1.txt": "Вісім крихітних душ потрапили до притулку. Сім із них знайшли дім. Залишився лише один — найбільший, із найбільшим темпераментом. Через рік, цілком випадково, він зустрів Матея, який собаки не планував. Проскочила іскра, і від червня 2017 вони разом крокують життям.",
  "onepage.hbook.1.cap": "Вісім у коробці",
  "onepage.hbook.2.ini": "В",
  "onepage.hbook.2.lead": "рятував людське життя. Прийшов у найважчий його період.",
  "onepage.hbook.2.txt": "У найтемніші часи він був для Матея опорою — витягнув його зі злих думок, із квартири на природу. Спершу вони відкривали найближчі вулички, потім лісочки та гори. Пройшли всю Словаччину (820 км) і здійснили road trip-и Європою. Їх поєднали пригоди та вільне життя в дорозі.",
  "onepage.hbook.2.cap": "З офісу у світ",
  "onepage.hbook.3.ini": "Й",
  "onepage.hbook.3.lead": "ого чиста душа принесла візію глобального руху для любителів собак.",
  "onepage.hbook.3.txt": "Життя з собакою — найкрасивіший розділ у житті кожної людини. Собачники — зовсім інший різновид людей: вони знову і знову розв'язують ті самі специфічні проблеми, і їх єднає любов до собак. А що, як перетворити цю історію на щось корисне?",
  "onepage.hbook.3.cap": "Народилася візія",
  "onepage.hbook.4.ini": "Д",
  "onepage.hbook.4.lead": "есять найкращих років за плечима, і щонайменше десять ще попереду!",
  "onepage.hbook.4.txt": "Hekthor надихнув Матея вивчати все про собак — психологію, дресирування, спорт, а найбільше — довголіття. Усі ці знання служитимуть усім у DOGYPT: не ще одна модна соцмережа, а мережа зі змістовним контентом. І все це завдяки «звичайному» псові з притулку.",
  "onepage.hbook.4.cap": "Засновник #1",
  "onepage.hbook.5.ini": "С",
  "onepage.hbook.5.lead": "ьогодні він живе в Словаччині — у лісах, горах і біля озер.",
  "onepage.hbook.5.txt": "Найбільше він любить апортувати з води. Він у чудовій формі, дуже розумний, скромний і найкращий компаньйон, якого можна побажати. Коли нас немає надворі, вдома вартує двох котів, Гері та Ібі, яких урятував з вулиці.",
  "onepage.hbook.5.cap": "Охоронець дому",
